function tallyTiles(m: number, n: number, dark: number[][]): number[] {
  const isDark = new Set(dark.map(([x, y]) => x * n + y));
  const tally = [0, 0, 0, 0, 0];
  for (let a = 0; a < m - 1; a++) {
    for (let b = 0; b < n - 1; b++) {
      let c = 0;
      for (const [dx, dy] of [[0, 0], [0, 1], [1, 0], [1, 1]]) if (isDark.has((a + dx) * n + b + dy)) c++;
      tally[c]++;
    }
  }
  return tally;
}

