function tallyTiles(m: number, n: number, dark: number[][]): number[] {
  const count = new Map<number, number>();
  for (const [x, y] of dark) {
    for (let a = x - 1; a <= x; a++) {
      for (let b = y - 1; b <= y; b++) {
        if (a < 0 || b < 0 || a > m - 2 || b > n - 2) continue;
        const key = a * n + b;
        count.set(key, (count.get(key) ?? 0) + 1);
      }
    }
  }
  const tally = [0, 0, 0, 0, 0];
  for (const c of count.values()) tally[c]++;
  tally[0] = (m - 1) * (n - 1) - count.size;
  return tally;
}

